import { useState } from "react";
import { AppProvider, useApp } from "./context/AppContext";
import { MesajProvider, useMesaj } from "./context/MesajContext";
import GirisEkrani from "./pages/GirisEkrani";
import AdminPanel from "./pages/admin/AdminPanel";
import IlanlarSayfasi from "./pages/kamyoncu/IlanlarSayfasi";
import KamyoncuProfil from "./pages/kamyoncu/ProfilSayfasi";
import { SeferlerSayfasi, MesajlarSayfasi } from "./pages/kamyoncu/DigerSayfalar";
import { IlanVerSayfasi, TekliflerSayfasi as TekliflerSayfasi2, MesajlarSayfasi as IssizMesajlarSayfasi, IssizProfilSayfasi } from "./pages/issiz/IssizSayfalar";
import { Header, BottomNav } from "./components/UI";
import "./index.css";

function MobilApp() {
  const { oturum } = useApp();
  const [sekme, setSekme] = useState(oturum?.rol === "kamyoncu" ? "ilanlar" : "ilanver");

  if (!oturum) return <div>Hata: oturum tanımsız</div>;

  const kamyoncuSayfalar = {
    ilanlar:  <IlanlarSayfasi />,
    seferler: <SeferlerSayfasi />,
    mesajlar: <MesajlarSayfasi onGeri={() => setSekme("ilanlar")} />,
    profil:   <KamyoncuProfil />,
  };
  const issizSayfalar = {
    ilanver:   <IlanVerSayfasi />,
    teklifler: <TekliflerSayfasi2 />,
    mesajlar:  <IssizMesajlarSayfasi onGeri={() => setSekme("ilanver")} />,
    profil:    <IssizProfilSayfasi />,
  };

  const sayfa = oturum.rol === "kamyoncu" ? kamyoncuSayfalar[sekme] : issizSayfalar[sekme];

  if (!sayfa) return <div>Sayfa bulunamadı: {sekme}</div>;

  return (
    <div className="app-shell">
      <Header />
      <div>{sayfa}</div>
      <BottomNav aktif={sekme} setAktif={setSekme} rol={oturum.rol} />
    </div>
  );
}

function AppIcerigi() {
  const { oturum } = useApp();
  console.log("oturum:", oturum);

  if (!oturum) {
    console.log("Giriş ekranını göster");
    return <GirisEkrani />;
  }

  if (oturum.rol === "admin") {
    console.log("Admin panelini göster");
    return <AdminPanel />;
  }

  console.log("Mobil app'i göster");
  return <MobilApp />;
}

export default function App() {
  return (
    <MesajProvider>
      <AppProvider>
        <AppIcerigi />
      </AppProvider>
    </MesajProvider>
  );
}
